reverse:
: main
  (forall ρ; ρ xs:Seq Int^many -- ρ reversed:Seq Int^many)
  locals { xs } {
    xs prim seq-int.len
    1 prim -
    xs
    prim seq-int.empty
    loop-reverse
  };

: loop-reverse
  (forall ρ; ρ i:Int^many xs:Seq Int^many result:Seq Int^many -- ρ reversed:Seq Int^many)
  locals { i xs result } {
    i 0 prim <
    [
      xs i prim seq-int.at
      result prim seq-int.push
      i 1 prim -
      xs
      loop-reverse
    ]
    [ result ]
    if
  };

has-pair-sum:
: main
  (forall ρ; ρ xs:Seq Int^many target:Int^many -- ρ found:Bool^many)
  locals { xs target } { 0 xs target loop-pair };

: loop-pair
  (forall ρ; ρ i:Int^many xs:Seq Int^many target:Int^many -- ρ found:Bool^many)
  locals { i xs target } {
    i xs prim seq-int.len prim <
    [
      i 1 prim + i xs target loop-pair-inner
    ]
    [ false ]
    if
  };

: loop-pair-inner
  (forall ρ; ρ j:Int^many i:Int^many xs:Seq Int^many target:Int^many -- ρ result:Bool^many)
  locals { j i xs target } {
    j xs prim seq-int.len prim <
    [
      xs i prim seq-int.at
      xs j prim seq-int.at
      prim +
      target prim =
      [ true ]
      [ j 1 prim + i xs target loop-pair-inner ]
      if
    ]
    [ i 1 prim + xs target loop-pair ]
    if
  };

digits:
: main
  (forall ρ; ρ n:Int^many -- ρ digits:Seq Int^many)
  locals { n } {
    n 0 prim =
    [ { 0 } ]
    [ n prim seq-int.empty loop-digits-collect ]
    if
  };

: loop-digits-collect
  (forall ρ; ρ num:Int^many result:Seq Int^many -- ρ digits:Seq Int^many)
  locals { num result } {
    num 0 prim =
    [ result loop-reverse-seq ]
    [
      num 10 prim mod
      result prim seq-int.push
      num 10 prim div
      result
      loop-digits-collect
    ]
    if
  };

: loop-reverse-seq
  (forall ρ; ρ seq:Seq Int^many -- ρ result:Seq Int^many)
  locals { seq } {
    seq prim seq-int.len
    1 prim -
    seq
    prim seq-int.empty
    loop-reverse-helper
  };

: loop-reverse-helper
  (forall ρ; ρ i:Int^many seq:Seq Int^many result:Seq Int^many -- ρ result:Seq Int^many)
  locals { i seq result } {
    i 0 prim <
    [
      seq i prim seq-int.at
      result prim seq-int.push
      i 1 prim -
      seq result
      loop-reverse-helper
    ]
    [ result ]
    if
  };

ledger:
: main
  (forall ρ; ρ start:Int^many txs:Seq Int^many -- ρ balance:Int^many rejected:Int^many)
  locals { start txs } { start 0 0 txs loop-ledger };

: loop-ledger
  (forall ρ; ρ balance:Int^many rejected:Int^many i:Int^many txs:Seq Int^many -- ρ balance:Int^many rejected:Int^many)
  locals { balance rejected i txs } {
    i txs prim seq-int.len prim <
    [
      txs i prim seq-int.at
      locals { tx } {
        balance tx prim +
        dup 0 prim <
        [
          drop
          balance
          rejected 1 prim +
        ]
        [
          rejected
        ]
        if
      }
      i 1 prim +
      txs
      loop-ledger
    ]
    [ balance rejected ]
    if
  };
